"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["68832"],{82020(e){e.exports=JSON.parse('{"id":"FIN-995","slug":"moving-average","term":"Moving Average","also_known_as":[],"difficulty":"Intermediate","definition":"A moving average is the average of a set of data points over a fixed number of recent periods, recalculated each period as new data is added and the oldest data is dropped.","explanation":["Moving averages smooth out short-term fluctuations, making it easier to see underlying trends in data such as share prices, sales figures or economic statistics.","For example, a three-day moving average of a share price that closed at 10, 12 and 14 over three days is 12. The next day, if the price closes at 13, the oldest value is dropped and the new average is calculated from 12, 14 and 13, giving 13.","A simple moving average gives equal weight to each data point. An exponential moving average gives more weight to recent data, so it responds more quickly to changes.","Moving averages are widely used in technical analysis. Traders often watch 50-day and 200-day moving averages of share prices. A price above its moving average may be seen as a sign of an upward trend. When a shorter moving average crosses above a longer one, some traders view it as a buy signal.","Moving averages lag behind the data, because they are based on past values. The longer the period, the smoother the line but the slower it reacts to changes. They are also used in statistics and economics to identify trends and reduce the effect of random variation."],"note":"","total":1500,"prev":{"slug":"mortgage-insurance","term":"Mortgage Insurance"},"next":{"slug":"multiple-regression","term":"Multiple Regression"}}')}}]);